package br.com.eventmenu.go.data

import br.com.eventmenu.go.security.SecureSessionStore
import org.json.JSONArray
import org.json.JSONObject

class ReceiptRepository(baseUrl:String,deviceId:String,private val sessionStore:SecureSessionStore){
 private val api=ApiClient(baseUrl,deviceId)
 suspend fun order(orderId:Int):OrderReceipt{require(orderId>0){"Pedido inválido."};val root=api.getReceipt("order",requireToken(),mapOf("order_id" to orderId.toString()));val r=root.optJSONObject("receipt")?:throw ApiException("O servidor não retornou um comprovante válido.",502);val itemsJson=r.optJSONArray("items")?:JSONArray();val paymentsJson=r.optJSONArray("payments")?:JSONArray();val items=buildList{for(i in 0 until itemsJson.length()){val x=itemsJson.optJSONObject(i)?:continue;add(ReceiptItem(clean(x.opt("name_snapshot"),"Item"),flexDouble(x,"quantity",1.0),flexInt(x,"unit_price_cents"),flexInt(x,"total_cents")))}};val payments=buildList{for(i in 0 until paymentsJson.length()){val x=paymentsJson.optJSONObject(i)?:continue;add(ReceiptPayment(flexInt(x,"id"),clean(x.opt("provider")),clean(x.opt("method")),flexInt(x,"amount_cents"),clean(x.opt("status")),clean(x.opt("verified_at"))))}};return OrderReceipt(clean(r.opt("receipt_number")),clean(r.opt("tenant_name"),"EventMenu"),flexInt(r,"order_id",orderId),clean(r.opt("channel")),clean(r.opt("status")),clean(r.opt("payment_status")),clean(r.opt("customer_name")),clean(r.opt("customer_phone")),clean(r.opt("table_name")),flexInt(r,"subtotal_cents"),flexInt(r,"discount_cents"),flexInt(r,"delivery_fee_cents"),flexInt(r,"total_cents"),flexInt(r,"paid_cents"),clean(r.opt("created_at")),items,payments)}
 suspend fun group(groupId:Int):GroupReceipt{require(groupId>0){"Divisão inválida."};val root=api.getReceipt("group",requireToken(),mapOf("group_id" to groupId.toString()));val r=root.optJSONObject("receipt")?:throw ApiException("O servidor não retornou o comprovante da divisão.",502);val aa=r.optJSONArray("allocations")?:JSONArray();val ii=r.optJSONArray("items")?:JSONArray();val allocations=buildList{for(i in 0 until aa.length()){val x=aa.optJSONObject(i)?:continue;add(GroupReceiptAllocation(flexInt(x,"order_id"),flexInt(x,"payment_id"),flexInt(x,"amount_cents"),clean(x.opt("payment_status")),clean(x.opt("verified_at"))))}};val items=buildList{for(i in 0 until ii.length()){val x=ii.optJSONObject(i)?:continue;add(GroupReceiptItem(flexInt(x,"order_item_id"),flexInt(x,"order_id"),clean(x.opt("name_snapshot"),"Item"),flexDouble(x,"quantity",1.0),flexInt(x,"amount_cents")))}};return GroupReceipt(clean(r.opt("receipt_number")),clean(r.opt("tenant_name"),"EventMenu"),flexInt(r,"group_id",groupId),if(r.isNull("tab_id"))null else flexInt(r,"tab_id"),clean(r.opt("table_name")),clean(r.opt("tab_label")),clean(r.opt("operator_name")),clean(r.opt("split_type")),clean(r.opt("method")),clean(r.opt("provider")),clean(r.opt("status")),flexInt(r,"amount_cents"),flexInt(r,"confirmed_cents"),clean(r.opt("provider_payment_id")),clean(r.opt("verified_at")),clean(r.opt("created_at")),allocations,items)}
 fun shareText(r:OrderReceipt)=buildString{appendLine(r.tenantName);appendLine("EVENTMENU GO · COMPROVANTE");appendLine(r.receiptNumber);appendLine("Pedido #${r.orderId} · ${channelLabel(r.channel)}");appendLine("Data: ${r.createdAt}");if(r.customerName.isNotBlank())appendLine("Cliente: ${r.customerName}");if(r.tableName.isNotBlank())appendLine("Mesa: ${r.tableName}");appendLine("--------------------------------");r.items.forEach{appendLine("${qty(it.quantity)}x ${it.name}  ${money(it.totalCents)}")};appendLine("--------------------------------");appendLine("Subtotal: ${money(r.subtotalCents)}");if(r.discountCents>0)appendLine("Desconto: -${money(r.discountCents)}");if(r.deliveryFeeCents>0)appendLine("Entrega: ${money(r.deliveryFeeCents)}");appendLine("TOTAL: ${money(r.totalCents)}");appendLine("Pago confirmado: ${money(r.paidCents)}");appendLine("--------------------------------");appendLine("Pagamentos");r.payments.forEach{appendLine("${methodLabel(it.method,it.provider)} · ${money(it.amountCents)} · ${statusLabel(it.status)}")};appendLine("--------------------------------");appendLine("Confirmação gerada pelo servidor EventMenu.")}
 fun shareText(r:GroupReceipt)=buildString{appendLine(r.tenantName);appendLine("EVENTMENU GO · COMPROVANTE DA DIVISAO");appendLine(r.receiptNumber);if(r.tableName.isNotBlank())appendLine("Mesa: ${r.tableName}");r.tabId?.let{appendLine("Comanda #$it${if(r.tabLabel.isNotBlank())" · ${r.tabLabel}" else ""}")};appendLine("Divisao: ${splitLabel(r.splitType)}");appendLine("Forma: ${methodLabel(r.method,r.provider)}");appendLine("Data: ${r.verifiedAt.ifBlank{r.createdAt}}");if(r.operatorName.isNotBlank())appendLine("Operador: ${r.operatorName}");appendLine("--------------------------------");if(r.items.isNotEmpty()){appendLine("Produtos desta parte");r.items.forEach{appendLine("${qty(it.quantity)}x ${it.name} · Pedido #${it.orderId} · ${money(it.amountCents)}")};appendLine("--------------------------------")};appendLine("Alocacao por pedido");r.allocations.forEach{appendLine("Pedido #${it.orderId} · ${money(it.amountCents)} · ${statusLabel(it.paymentStatus)}")};appendLine("--------------------------------");appendLine("VALOR DESTA PARTE: ${money(r.amountCents)}");appendLine("Confirmado: ${money(r.confirmedCents)}");if(r.providerPaymentId.isNotBlank())appendLine("Transacao: ${r.providerPaymentId}");appendLine("Status: ${statusLabel(r.status)}");appendLine("--------------------------------");appendLine("Pagamento distribuido pelo servidor entre os pedidos originais da comanda.")}
 private fun clean(v:Any?,fallback:String=""):String{if(v==null||v==JSONObject.NULL)return fallback;val s=v.toString().trim();return if(s.isBlank()||s.equals("null",true)||s.equals("undefined",true))fallback else s}
 private fun flexInt(o:JSONObject,k:String,d:Int=0)=when(val v=o.opt(k)){is Number->v.toInt();is String->v.trim().toDoubleOrNull()?.toInt()?:d;else->d}
 private fun flexDouble(o:JSONObject,k:String,d:Double=0.0)=when(val v=o.opt(k)){is Number->v.toDouble();is String->v.trim().replace(',','.').toDoubleOrNull()?:d;else->d}
 private fun qty(v:Double)=if(v%1.0==0.0)v.toInt().toString() else v.toString()
 private fun requireToken()=sessionStore.token()?:throw ApiException("Sessão não encontrada.",401)
 private fun money(c:Int)="R$ %.2f".format(c/100.0).replace('.',',')
 private fun channelLabel(v:String)=when(v){"counter"->"Balcão";"pickup"->"Retirada";"table"->"Mesa";"delivery"->"Delivery";"event"->"Evento";"bar"->"Bar";else->v}
 private fun methodLabel(m:String,p:String)=when(m.lowercase()){"cash"->"Dinheiro";"pix"->"PIX";"nfc"->"Cartão NFC";"card"->"Cartão";else->p.replaceFirstChar{if(it.isLowerCase())it.titlecase() else it.toString()}}
 private fun splitLabel(v:String)=when(v){"value"->"Por valor";"percentage"->"Por percentual";"person"->"Por pessoa";"product"->"Por produto";else->v}
 private fun statusLabel(v:String)=when(v){"paid"->"Confirmado";"refunded"->"Estornado";"partially_refunded"->"Estorno parcial";"duplicate_paid"->"Duplicado";"attention"->"Atenção";else->v}
}
